function num(v, d = 0) {
  const n = Number(v);
  return Number.isFinite(n) ? n : d;
}
function clamp(v, min, max) {
  return Math.max(min, Math.min(max, v));
}
function round(v, d = 4) {
  if (!Number.isFinite(v)) return null;
  return Number(v.toFixed(d));
}
function normText(v, fallback = '') {
  return String(v || fallback).trim();
}
function lower(v, fallback = '') {
  return normText(v, fallback).toLowerCase();
}
function uniq(arr) {
  return [...new Set((arr || []).filter(Boolean))];
}
function pickDominantLoss(availability, performance, quality) {
  const losses = {
    availability: clamp(1 - num(availability, 0), 0, 1),
    performance: clamp(1 - num(performance, 0), 0, 1),
    quality: clamp(1 - num(quality, 0), 0, 1)
  };
  let dominantLoss = 'availability';
  let maxLoss = losses.availability;
  for (const [k, v] of Object.entries(losses)) {
    if (v > maxLoss) {
      dominantLoss = k;
      maxLoss = v;
    }
  }
  return { dominantLoss, losses };
}

const assetMap = flow.get('acsm_asset_map') || {};
const bases = flow.get('acsm_bases') || ['cps1', 'cps5', 'cps7'];
const cpsList = Array.isArray(snapshot.cps) ? snapshot.cps : [];

const roleHints = {
  'CPS-001': 'welding',
  'CPS-005': 'quality_inspection',
  'CPS-007': 'transport'
};

// ============================================================
// 1) Enriquecer cada CPS com cognition local
// ============================================================
const enriched = cpsList.map((item) => {
  const base = item.baseTopic || lower(item.cpsId || item.cpsName || 'unknown');
  const meta = assetMap[base] || {};

  const learningDoc = global.get(`last_learning_${base}`) || null;
  const reasoningDoc = global.get(`last_reasoning_${base}`) || null;
  const healthDoc = global.get(`last_health_${base}`) || null;
  const operationalDoc = global.get(`last_operational_${base}`) || null;

  const learning = learningDoc?.learning || {};
  const reasoning = reasoningDoc?.reasoning || {};
  const health = healthDoc?.health || {};
  const operational = operationalDoc?.operational || {};

  const availability = num(item.availability, 0);
  const performance = num(item.performance, 0);
  const quality = num(item.quality, 0);
  const oee = num(item.global, 0);

  const { dominantLoss: dominantLossByOee, losses } =
    pickDominantLoss(availability, performance, quality);

  const localDominantLoss =
    lower(reasoning?.dominantLoss) || dominantLossByOee;

  const anomalyScore = clamp(
    num(learning?.anomalyScore ?? learning?.anomaly ?? 0, 0),
    0,
    1
  );

  const driftScore = clamp(
    num(learning?.driftScore ?? learning?.drift ?? 0, 0),
    0,
    1
  );

  const confidence = clamp(
    num(learning?.confidence ?? reasoning?.learningSummary?.confidence ?? 0.5, 0.5),
    0,
    1
  );

  const learningPattern =
    normText(learning?.pattern || learning?.state || learning?.type || 'unknown_local_pattern');

  const probableCause =
    normText(reasoning?.probableCause || reasoning?.cause || 'unknown');

  const healthState = lower(
    health?.healthState || health?.state || health?.status || 'unknown'
  );

  const featureStatus = lower(
    reasoning?.processEnvelope?.featureStatus ||
    operational?.process?.featureStatus ||
    operational?.featureStatus ||
    health?.featureStatus ||
    'unknown'
  );

  let healthPenalty = 0;
  if (
    healthState.includes('bad') ||
    healthState.includes('critical') ||
    healthState.includes('failure')
  ) {
    healthPenalty = 1;
  } else if (
    healthState.includes('warn') ||
    healthState.includes('degraded') ||
    healthState.includes('maintenance')
  ) {
    healthPenalty = 0.6;
  } else if (
    featureStatus === 'awaiting_replacement' ||
    featureStatus === 'failure'
  ) {
    healthPenalty = 0.9;
  } else if (featureStatus === 'maintenance') {
    healthPenalty = 0.5;
  }

  const localRiskText = lower(
    learning?.dominantRisk ||
    learning?.riskLevel ||
    reasoning?.severity ||
    'normal'
  );

  let localRiskScore = 0;
  if (localRiskText.includes('high') || localRiskText.includes('critical')) localRiskScore = 1;
  else if (localRiskText.includes('medium') || localRiskText.includes('warn')) localRiskScore = 0.6;
  else if (localRiskText.includes('low') || localRiskText.includes('normal') || localRiskText.includes('stable')) localRiskScore = 0.2;
  else localRiskScore = 0.4;

  const localEvidence = uniq([
    ...(Array.isArray(learning?.evidence) ? learning.evidence : []),
    ...(Array.isArray(reasoning?.evidence) ? reasoning.evidence : [])
  ]);

  const propagationPotential = clamp(
    (localDominantLoss === 'availability' ? 0.30 : 0.15) +
    (anomalyScore * 0.25) +
    (driftScore * 0.15) +
    (healthPenalty * 0.20) +
    (localRiskScore * 0.10),
    0,
    1
  );

  // Score de criticidade enriquecido
  const oeeLoss = clamp(1 - oee, 0, 1);
  const availabilityLoss = losses.availability;
  const performanceLoss = losses.performance;
  const qualityLoss = losses.quality;

  const criticalityScore = clamp(
    0.25 * oeeLoss +
    0.20 * availabilityLoss +
    0.15 * performanceLoss +
    0.10 * qualityLoss +
    0.10 * anomalyScore +
    0.08 * driftScore +
    0.07 * healthPenalty +
    0.05 * propagationPotential,
    0,
    1
  );

  return {
    cpsId: item.cpsId || meta.cpsId || base.toUpperCase(),
    cpsName: item.cpsName || meta.cpsName || base,
    baseTopic: base,
    role: item.role || meta.role || roleHints[item.cpsId] || 'generic',
    plant: item.plant || meta.plant || 'unknown',
    assetType: item.assetType || meta.assetType || 'unknown',

    oee: round(oee),
    availability: round(availability),
    performance: round(performance),
    quality: round(quality),

    dominantLoss: localDominantLoss,
    criticalityScore: round(criticalityScore),

    criticalityDetails: {
      oeeLoss: round(oeeLoss),
      availabilityLoss: round(availabilityLoss),
      performanceLoss: round(performanceLoss),
      qualityLoss: round(qualityLoss),
      anomalyContribution: round(anomalyScore),
      driftContribution: round(driftScore),
      healthContribution: round(healthPenalty),
      propagationPotential: round(propagationPotential),
      confidence: round(confidence)
    },

    localCognition: {
      learningPattern,
      probableCause,
      anomalyScore: round(anomalyScore),
      driftScore: round(driftScore),
      confidence: round(confidence),
      localRiskText,
      featureStatus,
      healthState,
      evidence: localEvidence
    }
  };
});

