      ...(inspection.localCognition.evidence || []).slice(0, 2),
      ...(transport.localCognition.evidence || []).slice(0, 2)
    ])
  };

  if (!lossPropagation.detected || candidate.confidence > lossPropagation.confidence) {
    lossPropagation = candidate;
  }
  crossCpsPatterns.push('inspection_hold_impacts_transport_flow');
}

// fallback simples
if (!lossPropagation.detected && criticality.length >= 2) {
  const first = criticality[0];
  const second = criticality[1];
  if (first.oee < 0.70 && second.oee < 0.78) {
    lossPropagation = {
      detected: true,
      from: first.cpsId,
      to: second.cpsId,
      type: 'possible_cascade_effect',
      confidence: 0.68,
      evidence: uniq([
        'multiple_cps_underperforming',
        first.dominantLoss,
        second.dominantLoss
      ])
    };
    crossCpsPatterns.push('multi_asset_degradation_cluster');
  }
}

// ============================================================
// 5) SincronizaÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â§ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â£o sistÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Âªmica
// ============================================================
const oees = criticality.map(c => num(c.oee, 0));
const maxOee = oees.length ? Math.max(...oees) : 0;
const minOee = oees.length ? Math.min(...oees) : 0;
const oeeSpread = maxOee - minOee;

const anomalyValues = criticality.map(c => num(c.localCognition?.anomalyScore, 0));
const maxAnomaly = anomalyValues.length ? Math.max(...anomalyValues) : 0;
const minAnomaly = anomalyValues.length ? Math.min(...anomalyValues) : 0;
const riskSpread = maxAnomaly - minAnomaly;

const statusSet = uniq(criticality.map(c => c.localCognition?.featureStatus).filter(Boolean));
const statusDiversity = statusSet.length;

let synchronizationState = 'acceptable';
if (oeeSpread > 0.20 || riskSpread > 0.30 || statusDiversity >= 3) {
  synchronizationState = 'poor';
} else if (oeeSpread > 0.12 || riskSpread > 0.18) {
  synchronizationState = 'attention';
}

const synchronization = {
  state: synchronizationState,
  spread: round(oeeSpread),
  riskSpread: round(riskSpread),
  statusDiversity,
  confidence: synchronizationState === 'poor' ? 0.82 : synchronizationState === 'attention' ? 0.72 : 0.64
};

// ============================================================
// 6) EvidÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Âªncias sistÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Âªmicas
// ============================================================
const dominantSignals = [];
const localCognitionInputs = criticality.map(c => ({
  cpsId: c.cpsId,
  cpsName: c.cpsName,
  role: c.role,
  dominantLoss: c.dominantLoss,
  learningPattern: c.localCognition.learningPattern,
  probableCause: c.localCognition.probableCause,
  anomalyScore: c.localCognition.anomalyScore,
  driftScore: c.localCognition.driftScore,
  confidence: c.localCognition.confidence,
  featureStatus: c.localCognition.featureStatus,
  healthState: c.localCognition.healthState,
  evidence: c.localCognition.evidence
}));

