function slopeOf(arr) {
  if (!Array.isArray(arr) || arr.length < 2) return 0;
  const first = num(arr[0], 0);
  const last = num(arr[arr.length - 1], 0);
  return (last - first) / Math.max(1, arr.length - 1);
}
function mean(arr) {
  const valid = (arr || []).map(x => Number(x)).filter(Number.isFinite);
  if (!valid.length) return 0;
  return valid.reduce((a, b) => a + b, 0) / valid.length;
}
function stddev(arr) {
  const valid = (arr || []).map(x => Number(x)).filter(Number.isFinite);
  if (valid.length < 2) return 0;
  const m = mean(valid);
  const variance = mean(valid.map(v => Math.pow(v - m, 2)));
  return Math.sqrt(variance);
}
function trendOfHistory(history) {
  if (!Array.isArray(history) || history.length < 3) return 'stable';
  const values = history.map(x => num(x.oee, 0));
  const delta = values[values.length - 1] - values[0];
  if (delta > 0.03) return 'up';
  if (delta < -0.03) return 'down';
  return 'stable';
}

