        sensores: lastState,
        tempo_sem_receber_dado_ms: timeSinceSeen
      }
    },
    retain: true,
    qos: 1
  };

  const out2 = buildAwaitingOutput(out1);

  outLog = buildLog(
    "FEATURE_STATE_CHANGED_BY_TICK",
    {
      previousStatus: prev,
      newStatus: status,
      details: out1.payload.details
    },
    status === "awaiting_replacement" ? "WARN" : "INFO",
    out1.topic
  );

  return [out1, out2, null, outLog];
}

