// 1) Entradas
// --------------------------------------------------
const playEnabled = flow.get("playEnabled") === true;
const featureStatus = String(p.status || p.sourceStatus || "").toLowerCase().trim();

const live = flow.get("aas_cps5_live") || {};
const op = live.operationalData || {};

const currentTemperature = num(op.CurrentTemperature, 35);
const currentRPM = num(op.CurrentRPM, 1450);
const currentTorque = num(op.CurrentTorque, 14);
const pieceCounterAbs = num(op.PieceCounter, 0);

// ideal nominal
const IDEAL_CYCLE_TIME_MS = 3000;

// --------------------------------------------------
// 2) Estados considerados parada
// --------------------------------------------------
const DOWNTIME_STATES = new Set([
    "maintenance",
    "awaiting_replacement",
    "failure",
    "stopped",
    "unplugged"
]);

const isOperationalNow = playEnabled && !DOWNTIME_STATES.has(featureStatus);

// --------------------------------------------------
// 3) Estado anterior
// --------------------------------------------------
const prevTs = num(flow.get("oee_prevTs"), now);
const prevStatus = String(flow.get("oee_prevStatus") || "").toLowerCase().trim();
const prevPlayEnabled = flow.get("oee_prevPlayEnabled") === true;
const prevPieceCounterAbs = num(flow.get("oee_prevPieceCounterAbs"), pieceCounterAbs);

let plannedProductionTimeMs = num(flow.get("oee_plannedProductionTimeMs"), 0);
let downtimeMs = num(flow.get("oee_downtimeMs"), 0);
let operatingTimeMs = num(flow.get("oee_operatingTimeMs"), 0);

let totalPieces = num(flow.get("oee_totalPieces"), 0);
let goodPieces = num(flow.get("oee_goodPieces"), 0);
let rejectPieces = num(flow.get("oee_rejectPieces"), 0);

let lastValidCycleTimeMs = num(flow.get("oee_lastValidCycleTimeMs"), 0);
let lastPerformanceDisplay = num(flow.get("oee_lastPerformanceDisplay"), 0);
let lastWindowCycleTimeMs = num(flow.get("oee_lastWindowCycleTimeMs"), 0);

// --------------------------------------------------
// 4) Delta de tempo
// --------------------------------------------------
const deltaMsRaw = Math.max(0, now - prevTs);

// limita saltos exagerados para nÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â£o distorcer OEE
const deltaMs = Math.min(deltaMsRaw, 10000);

// --------------------------------------------------
// 5) Planejado / downtime / operating
// Usa estado anterior para acumular o intervalo encerrado
// --------------------------------------------------
const prevWasOperational =
    prevPlayEnabled && !DOWNTIME_STATES.has(prevStatus);

if (prevPlayEnabled) {
    plannedProductionTimeMs += deltaMs;
}

if (prevPlayEnabled && DOWNTIME_STATES.has(prevStatus)) {
    downtimeMs += deltaMs;
}

let deltaOperatingTimeMs = 0;

if (prevWasOperational) {
    operatingTimeMs += deltaMs;
    deltaOperatingTimeMs = deltaMs;
}

// --------------------------------------------------
// 6) ProduÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â§ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â£o
// --------------------------------------------------
let producedDelta = pieceCounterAbs - prevPieceCounterAbs;
if (!Number.isFinite(producedDelta) || producedDelta < 0) {
    producedDelta = 0;
}

// proteÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â§ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â£o: se hÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¡ produÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â§ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â£o mas a janela operacional veio zerada,
// tenta recuperar coerÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Âªncia usando o estado atual
