    return null;
}

const oldValue = Boolean(previous[field]);
const newValue = Boolean(value);
const risingEdge = !oldValue && newValue;
previous[field] = newValue;
flow.set("cpslai1_production_prev", previous);
if (!risingEdge) return null;

