// ============================================================

const rawLifecyclePhase =
    flow.get("cpslai1_lifecycle_phase") ??
    global.get("cpslai1_lifecycle_phase") ??
    null;

const lifecyclePhase =
    rawLifecyclePhase === null ||
    rawLifecyclePhase === undefined
        ? null
        : String(rawLifecyclePhase).trim().toLowerCase();


// ============================================================
// 2. MODO DE OPERAÇÃO
//
// Derivado somente de marcadores fisicamente validados.
//
// INIT         -> GCT_0
// MANUAL       -> sys_man
// STEP_BY_STEP -> man_step_1
// AUTOMATIC    -> sup_step_1
//
// operationMode é independente de operationalState.
// ============================================================

let operationMode = "UNKNOWN";
let operationModeSource = null;

if (val("InitModeSignal") === true) {

    operationMode = "INIT";
    operationModeSource = "GCT_0";

} else if (val("ManualModeSignal") === true) {

    operationMode = "MANUAL";
    operationModeSource = "sys_man";

} else if (val("StepByStepModeSignal") === true) {

    operationMode = "STEP_BY_STEP";
    operationModeSource = "man_step_1";

} else if (val("AutomaticModeSignal") === true) {

    operationMode = "AUTOMATIC";
    operationModeSource = "sup_step_1";
}


// ============================================================
// 3. LIMIAR DE INATIVIDADE
//
// 5000 ms validado experimentalmente em 03/10/2026.
// ============================================================

const configuredInactivityThresholdMs =
    flow.get("cpslai1_stopped_inactivity_threshold_ms") ??
    global.get("cpslai1_stopped_inactivity_threshold_ms") ??
    5000;

const inactivityThresholdMs =
    Number.isFinite(Number(configuredInactivityThresholdMs)) &&
    Number(configuredInactivityThresholdMs) > 0
        ? Number(configuredInactivityThresholdMs)
        : null;


// ============================================================
// 4. EVIDÊNCIA DE ATIVIDADE FÍSICA
// ============================================================

const lastPhysicalActivityMs =
    flow.get("cpslai1_last_physical_activity_ms") ?? null;

const lastPhysicalActivityField =
    flow.get("cpslai1_last_physical_activity_field") ?? null;

const lastPhysicalActivityTag =
    flow.get("cpslai1_last_physical_activity_tag") ?? null;

const physicalActivityAgeMs =
    lastPhysicalActivityMs !== null
        ? Math.max(
            0,
            nowMs - Number(lastPhysicalActivityMs)
        )
        : null;

let physicalActivityState = "UNKNOWN";

if (
    physicalActivityAgeMs !== null &&
    inactivityThresholdMs !== null
) {

    physicalActivityState =
        physicalActivityAgeMs <= inactivityThresholdMs
            ? "RECENT"
            : "INACTIVE_WINDOW_EXCEEDED";

} else if (lastPhysicalActivityMs !== null) {

    physicalActivityState = "OBSERVED";
}


// ============================================================
// 5. ESTADO OPERACIONAL
//
// Regra adotada:
//
// comunicação inválida
//   -> UNKNOWN
//
// STEP_BY_STEP
//   -> MAINTENANCE
//
// play + AUTOMATIC + atividade recente
//   -> RUNNING
//
// play + AUTOMATIC + inatividade > 5000 ms
//   -> STOPPED
//
// demais situações
//   -> UNKNOWN
//
// IMPORTANTE:
// MAINTENANCE é uma inferência do protótipo baseada no modo
// STEP_BY_STEP fisicamente validado no CPS-LAI-01.
// ============================================================

let operationalState = "UNKNOWN";
let operationalStateReason = "INSUFFICIENT_EVIDENCE";
let operationalStateEvidenceSource = "INSUFFICIENT_EVIDENCE";

if (!dataFresh) {

    operationalState = "UNKNOWN";
    operationalStateReason =
        "COMMUNICATION_NOT_FRESH";

    operationalStateEvidenceSource =
        "COMMUNICATION_STATUS";

} else if (operationMode === "STEP_BY_STEP") {

    operationalState = "MAINTENANCE";

    operationalStateReason =
        "INFERRED_MAINTENANCE_FROM_STEP_BY_STEP_MODE";

    operationalStateEvidenceSource =
        "PHYSICALLY_VALIDATED_STEP_BY_STEP_MODE_MARKER";

} else if (
    lifecyclePhase === "play" &&
    operationMode === "AUTOMATIC"
) {

    if (
        inactivityThresholdMs === null ||
        lastPhysicalActivityMs === null
    ) {

        operationalState = "UNKNOWN";

        operationalStateReason =
            inactivityThresholdMs === null
                ? "INACTIVITY_THRESHOLD_NOT_VALIDATED"
                : "NO_PHYSICAL_ACTIVITY_EVIDENCE";

        operationalStateEvidenceSource =
            "PHYSICALLY_VALIDATED_SENSORS";

    } else if (
        physicalActivityAgeMs <= inactivityThresholdMs
    ) {

        operationalState = "RUNNING";

        operationalStateReason =
            "RECENT_PHYSICAL_ACTIVITY_ON_VALIDATED_SENSOR";

        operationalStateEvidenceSource =
            "PHYSICALLY_VALIDATED_SENSORS";

    } else {

        operationalState = "STOPPED";

        operationalStateReason =
            "PHYSICAL_INACTIVITY_THRESHOLD_EXCEEDED";

        operationalStateEvidenceSource =
            "PHYSICALLY_VALIDATED_SENSORS";
    }

} else if (operationMode === "MANUAL") {

    operationalState = "UNKNOWN";

    operationalStateReason =
        "MANUAL_MODE_WITHOUT_MAINTENANCE_INFERENCE";

    operationalStateEvidenceSource =
        "PHYSICALLY_VALIDATED_MANUAL_MODE_MARKER";

} else if (operationMode === "INIT") {

    operationalState = "UNKNOWN";

    operationalStateReason =
        "INITIALIZATION_MODE";

    operationalStateEvidenceSource =
        "PHYSICALLY_VALIDATED_INIT_MODE_MARKER";

} else {

    operationalState = "UNKNOWN";

    operationalStateReason =
        "INSUFFICIENT_EVIDENCE";

    operationalStateEvidenceSource =
        "INSUFFICIENT_EVIDENCE";
}


// ============================================================
// 6. DATA PAYLOAD
// ============================================================

const data = {

    schemaVersion: "1.0",
    cpsId: "cpslai1",

    assetName:
        "DistributionConveyorStationLAI",

    displayName:
        "CPS-LAI-01 – Distribution/Conveyor Station",

    source: "OPC_UA",

    endpoint:
        "opc.tcp://192.168.1.10:4840",

    timestamp: nowIso,

    PieceAtEntry:
        val("PieceAtEntry"),

    PieceAtMiddle:
        val("PieceAtMiddle"),

    PieceAtExit:
        val("PieceAtExit"),

    SlideRetracted:
        val("SlideRetracted"),

    SlideExtended:
        val("SlideExtended"),

    MagazineFeedSensor:
        val("MagazineFeedSensor"),

    AlarmSignal:
        val("AlarmSignal"),

    operationMode,

    physicalActivity: {

        lastActivityAt:
            lastPhysicalActivityMs !== null
                ? new Date(
                    Number(lastPhysicalActivityMs)
                ).toISOString()
                : null,

        ageMs:
            physicalActivityAgeMs,

        lastSourceField:
            lastPhysicalActivityField,

        lastSourceTag:
            lastPhysicalActivityTag,

        state:
            physicalActivityState,

        inactivityThresholdMs,

        inactivityThresholdEvidence:
            inactivityThresholdMs === 5000
                ? "EXPERIMENTALLY_VALIDATED_2026-10-03"
                : "CONFIGURED_OVERRIDE",

        evidenceSource:
            "PHYSICALLY_VALIDATED_SENSORS"
    },

    evidence: {

        PieceAtEntry:
            evidence("PieceAtEntry"),

        PieceAtMiddle:
            evidence("PieceAtMiddle"),

        PieceAtExit:
            evidence("PieceAtExit"),

        SlideRetracted:
            evidence("SlideRetracted"),

        SlideExtended:
            evidence("SlideExtended"),

        MagazineFeedSensor:
            evidence("MagazineFeedSensor"),

        AlarmSignal:
            evidence("AlarmSignal"),

        mode: {

            SysResSignal:
                evidence("SysResSignal"),

            ManualModeSignal:
                evidence("ManualModeSignal"),

            StepByStepModeSignal:
                evidence("StepByStepModeSignal"),

            AutomaticSupervisorStep0:
                evidence("AutomaticSupervisorStep0"),

            AutomaticModeSignal:
                evidence("AutomaticModeSignal"),

            InitModeSignal:
                evidence("InitModeSignal"),

            GCT4State:
                evidence("GCT4State")
        }
    }
};


// ============================================================
// 7. STATUS PAYLOAD
// ============================================================

const status = {

    schemaVersion: "1.0",
    cpsId: "cpslai1",
    timestamp: nowIso,

    lifecyclePhase,

    operationMode,

    operationModeEvidence: {

        sourceTag:
            operationModeSource,

        evidenceStatus:
            operationMode === "UNKNOWN"
                ? "INSUFFICIENT_EVIDENCE"
                : "PHYSICALLY_VALIDATED",

        InitModeSignal:
            val("InitModeSignal"),

        ManualModeSignal:
            val("ManualModeSignal"),

        StepByStepModeSignal:
            val("StepByStepModeSignal"),

        AutomaticModeSignal:
            val("AutomaticModeSignal")
    },

    operationalState,

    operationalStateEvidence: {

        reason:
            operationalStateReason,

        evidenceStatus:
            operationalState === "MAINTENANCE"
                ? "RULE_DERIVED_FROM_PHYSICALLY_VALIDATED_MODE"
                : operationalState === "RUNNING" ||
                  operationalState === "STOPPED"
                    ? "RULE_DERIVED_FROM_PHYSICAL_ACTIVITY"
                    : "INSUFFICIENT_OR_CONTEXTUAL_EVIDENCE",

        evidenceSource:
            operationalStateEvidenceSource,

        communicationFresh:
            dataFresh,

        lifecyclePhase,

        operationMode,

        operationModeSource,

        inactivityThresholdMs,

        inactivityThresholdEvidence:
            inactivityThresholdMs === 5000
                ? "EXPERIMENTALLY_VALIDATED_2026-10-03"
                : "CONFIGURED_OVERRIDE",

        lastPhysicalActivityAt:
            lastPhysicalActivityMs !== null
                ? new Date(
                    Number(lastPhysicalActivityMs)
                ).toISOString()
                : null,

        physicalActivityAgeMs,

        lastPhysicalActivityField,

        lastPhysicalActivityTag
    },

    physicalActivity: {

        state:
            physicalActivityState,

        lastActivityAt:
            lastPhysicalActivityMs !== null
                ? new Date(
                    Number(lastPhysicalActivityMs)
                ).toISOString()
                : null,

        ageMs:
            physicalActivityAgeMs,

        lastSourceField:
            lastPhysicalActivityField,

        lastSourceTag:
            lastPhysicalActivityTag,

        inactivityThresholdMs,

        inactivityThresholdEvidence:
            inactivityThresholdMs === 5000
                ? "EXPERIMENTALLY_VALIDATED_2026-10-03"
                : "CONFIGURED_OVERRIDE",

        evidenceSource:
            "PHYSICALLY_VALIDATED_SENSORS"
    },

    supervisorState: {

        supStep0:
            val("AutomaticSupervisorStep0"),

        supStep1:
            val("AutomaticModeSignal"),

        gct4:
            val("GCT4State")
    },

    communication: {

        dataFresh,

        dataAgeMs:
            ageMs,

        opcUaStatus:
            opcStatus
    },

    evidenceStatus:
        operationMode === "UNKNOWN"
            ? "PARTIAL_PHYSICAL_EVIDENCE"
            : "PHYSICALLY_VALIDATED_MODE",

    note:
        "Operational state is derived independently from lifecycle and operation mode. STEP_BY_STEP is interpreted by the prototype as MAINTENANCE; AUTOMATIC uses validated physical activity to derive RUNNING or STOPPED."
};


// ============================================================
// 8. OEE PARCIAL
// ============================================================

// ============================================================
// 8. OEE OPERACIONAL DERIVADO
//
// Availability = RUNNING / (RUNNING + STOPPED)
// Performance = referenceCycleTimeMs * completedCycles / runTime
// Quality = proxy de conclusão do processo = completedCycles / totalCount
//
// Quality NÃO representa inspeção de qualidade do produto.
// ============================================================

const referenceCycleTimeMs = 2020;

let oeeTime = flow.get("cpslai1_oee_time") || {
    lastTimestampMs: null,
    lastOperationalState: null,
    runTimeMs: 0,
    stoppedTimeMs: 0,
    maintenanceTimeMs: 0,
    unknownTimeMs: 0
};

if (oeeTime.lastTimestampMs !== null && Number.isFinite(Number(oeeTime.lastTimestampMs))) {
    const deltaMs = Math.max(0, Math.min(5000, nowMs - Number(oeeTime.lastTimestampMs)));
    switch (oeeTime.lastOperationalState) {
        case "RUNNING": oeeTime.runTimeMs += deltaMs; break;
        case "STOPPED": oeeTime.stoppedTimeMs += deltaMs; break;
        case "MAINTENANCE": oeeTime.maintenanceTimeMs += deltaMs; break;
        default: oeeTime.unknownTimeMs += deltaMs; break;
    }
}

oeeTime.lastTimestampMs = nowMs;
oeeTime.lastOperationalState = operationalState;
flow.set("cpslai1_oee_time", oeeTime);

const plannedProductionTimeMs = Number(oeeTime.runTimeMs || 0) + Number(oeeTime.stoppedTimeMs || 0);
const runTimeMs = Number(oeeTime.runTimeMs || 0);
const stoppedTimeMs = Number(oeeTime.stoppedTimeMs || 0);
const totalCount = Number(production.totalCount || 0);
const completedCycles = Number(production.completedCycles || 0);

const availability = plannedProductionTimeMs > 0
    ? Math.max(0, Math.min(1, runTimeMs / plannedProductionTimeMs))
    : null;

const performance = runTimeMs > 0 && totalCount > 0
    ? Math.max(0, Math.min(1, (referenceCycleTimeMs * totalCount) / runTimeMs))
    : null;

const qualityProxy = totalCount > 0
    ? 1.0
    : null;

const currentOee = availability !== null && performance !== null && qualityProxy !== null
    ? availability * performance * qualityProxy
    : null;

const oee = {
    schemaVersion: "1.0",
    cpsId: "cpslai1",
    timestamp: nowIso,
    calculationState: currentOee === null ? "PARTIAL" : "OPERATIONAL_OEE_PROXY",
    oee: {
        current: currentOee,
        availability: availability,
        performance: performance,
        quality: qualityProxy
    },
    time: {
        plannedProductionTimeMs,
        runTimeMs,
        stoppedTimeMs,
        maintenanceTimeMs: Number(oeeTime.maintenanceTimeMs || 0),
        unknownTimeMs: Number(oeeTime.unknownTimeMs || 0)
    },
    production: {
        totalCount,
        completedCycles,
        incompleteCycles: Number(production.incompleteCycles || 0),
        lastCycleTimeMs: production.lastCycleTimeMs ?? null,
        averageCycleTimeMs: production.averageCycleTimeMs ?? null,
        firstProductionTimestamp: production.firstProductionTimestamp ? new Date(production.firstProductionTimestamp).toISOString() : null,
        lastProductionTimestamp: production.lastProductionTimestamp ? new Date(production.lastProductionTimestamp).toISOString() : null,
        sampleCounts: production.sampleCounts || { PieceAtEntry: 0, PieceAtMiddle: 0, PieceAtExit: 0 },
        risingEdges: production.risingEdges || { PieceAtEntry: 0, PieceAtMiddle: 0, PieceAtExit: 0 }
    },
    cycle: {
        active: currentCycle !== null,
        startedAt: currentCycle ? new Date(currentCycle.startedAt).toISOString() : null,
        middleSeen: currentCycle ? Boolean(currentCycle.middleSeen) : false
    },
    reference: {
        cycleTimeMs: referenceCycleTimeMs,
        evidenceStatus: "EXPERIMENTAL_REFERENCE_PROVISIONAL",
        note: "Reference cycle time is provisional and based on one experimentally observed complete cycle."
    },
    performance: {
        countSource: "PieceAtExit",
        countSourceTag: "G1BG1",
        formula: "referenceCycleTimeMs * totalCount / runTimeMs"
    },
    quality: {
        type: "ASSUMED_CONFORMING_OUTPUT",
        productQualityValidated: false,
        assumedGoodCount: totalCount,
        assumedRejectCount: 0,
        formula: "assumed goodCount = totalCount; rejectCount = 0",
        evidenceStatus: "NO_VALIDATED_REJECT_SIGNAL"
    },
    evidence: {
        countSource: "PieceAtExit",
        countSourceTag: "G1BG1",
        cycleStartSource: "PieceAtEntry",
        cycleStartSourceTag: "G1BG3",
        cycleValidationSource: "PieceAtMiddle",
        cycleValidationSourceTag: "G1BG2",
        semanticStatus: {
            PieceAtEntry: "FIELD_VALIDATED",
            PieceAtMiddle: "FIELD_VALIDATED",
            PieceAtExit: "FIELD_VALIDATED"
        }
    },
    evidenceStatus: "SENSOR_DERIVED_OPERATIONAL_OEE",
    note: "Operational OEE derived from validated operational state and validated PieceAtExit counting. Quality is assumed as 100% because no validated reject signal is currently available; this is not validated product quality."
};


// ============================================================
// 9. PUBLICAÇÃO
// ============================================================

return [
    {
        payload: JSON.stringify(data)
    },
    {
        payload: JSON.stringify(status)
    },
    {
        payload: JSON.stringify(oee)
    }
];

flow.set("cpslai1_stopped_inactivity_threshold_ms", 5000);
global.set("cpslai1_latest", {});
global.set("cpslai1_last_update_ms", 0);
flow.set("cpslai1_physical_activity_values", {});
flow.set("cpslai1_last_physical_activity_ms", null);
flow.set("cpslai1_last_physical_activity_field", null);
flow.set("cpslai1_last_physical_activity_tag", null);
flow.set("cpslai1_production_prev", {});
flow.set("cpslai1_current_cycle", null);
flow.set("cpslai1_production_metrics", {
    totalCount: 0, completedCycles: 0, incompleteCycles: 0,
    lastCycleTimeMs: null, averageCycleTimeMs: null, cycleTimeSumMs: 0,
    firstProductionTimestamp: null, lastProductionTimestamp: null
});
node.warn("CPS-LAI-01 cache e métricas produtivas resetados");
return null;

// CPS-LAI-01 - lifecycle context recebido da ACSM
// Fonte autoritativa: ACSM / ciclo PPU
// Tópico: acsm/cpslai1/lifecycle

let data = msg.payload;

if (Buffer.isBuffer(data)) {
    data = data.toString("utf8");
}

if (typeof data === "string") {
    try {
        data = JSON.parse(data);
    } catch (err) {
        node.warn("ACSM lifecycle payload inválido: JSON não pôde ser interpretado");
        return null;
    }
}

if (!data || typeof data !== "object" || Array.isArray(data)) {
    node.warn("ACSM lifecycle payload inválido: objeto esperado");
    return null;
}

if (data.cpsId && String(data.cpsId).trim().toLowerCase() !== "cpslai1") {
    node.warn("ACSM lifecycle rejeitado: cpsId inesperado=" + String(data.cpsId));
    return null;
}

const allowed = ["plug", "play", "return", "unplug"];
const phase = String(data.lifecyclePhase || "").trim().toLowerCase();

if (!allowed.includes(phase)) {
    node.warn("ACSM lifecycle phase rejeitada: " + phase);
    return null;
}

const nowMs = Date.now();
flow.set("cpslai1_lifecycle_phase", phase);
flow.set("cpslai1_lifecycle_phase_ts", nowMs);
flow.set("cpslai1_lifecycle_phase_source", String(data.source || "ACSM"));
flow.set("cpslai1_lifecycle_phase_message_ts", data.timestamp || null);

node.warn("ACSM LIFECYCLE | cpslai1 | " + phase);

msg.payload = {
    cpsId: "cpslai1",
    lifecyclePhase: phase,
    source: String(data.source || "ACSM"),
    sourceTimestamp: data.timestamp || null,
    receivedAt: new Date(nowMs).toISOString()
};

return msg;

// Reset SOMENTE das métricas produtivas/OEE.
// Preserva cache OPC UA, Health, lifecycle e governance.
const latest = global.get("cpslai1_latest") || {};
function cachedBool(field) {
    const item = latest[field];
    return item && typeof item.value === "boolean" ? item.value : false;
}
const baseline = {
    PieceAtEntry: cachedBool("PieceAtEntry"),
    PieceAtMiddle: cachedBool("PieceAtMiddle"),
    PieceAtExit: cachedBool("PieceAtExit")
};
flow.set("cpslai1_production_prev", baseline);
flow.set("cpslai1_current_cycle", null);
flow.set("cpslai1_production_metrics", {
    totalCount: 0, completedCycles: 0, incompleteCycles: 0,
    lastCycleTimeMs: null, averageCycleTimeMs: null, cycleTimeSumMs: 0,
    firstProductionTimestamp: null, lastProductionTimestamp: null,
    sampleCounts: { PieceAtEntry: 0, PieceAtMiddle: 0, PieceAtExit: 0 },
    risingEdges: { PieceAtEntry: 0, PieceAtMiddle: 0, PieceAtExit: 0 }
});
flow.set("cpslai1_oee_time", {
    lastTimestampMs: null, lastOperationalState: null,
    runTimeMs: 0, stoppedTimeMs: 0, maintenanceTimeMs: 0, unknownTimeMs: 0
});
node.warn("PRODUCTION + OEE RESET v4 | baseline=" + JSON.stringify(baseline));
return null;

// Apenas eventos reportados pelo CPS-LAI-01
let status;
try {
  status = typeof msg.payload === 'string' ? JSON.parse(msg.payload) : msg.payload;
} catch (err) {
  node.warn('Status MQTT inválido: ' + err.message);
  return null;
}

if (!status || status.cpsId !== 'cpslai1') return null;

// Chaves no fluxo para controle de estado e tempo do último e-mail
const isAlertActive = flow.get('cpslai1_alert_intervention_active') === true;
const lastEmailSentAt = flow.get('cpslai1_last_email_sent_at') || 0;

const now = Date.now();
const EMAIL_INTERVAL_MS = 3 * 60 * 1000; // 3 minutos em milissegundos

// Detecta se está em modo MANUAL
const isManualMode = status.operationMode === 'MANUAL' ||
  status.evidence?.ManualModeSignal?.value === true;

if (isManualMode) {
  // Marca o alerta geral como ativo (para controle MQTT se necessário)
  if (!isAlertActive) {
    flow.set('cpslai1_alert_intervention_active', true);
  }

  // Verifica se já se passaram 3 minutos desde o último disparo de e-mail (ou se é o 1º envio)
  const shouldSendEmail = (now - lastEmailSentAt) >= EMAIL_INTERVAL_MS;

  const event = {
    schemaVersion: '1.0',
    cpsId: 'cpslai1',
    cpsName: 'CPS-LAI-01 — Distribution/Conveyor Station',
    eventType: 'HUMAN_INTERVENTION_REQUIRED',
    operationMode: 'MANUAL',
    operationalState: 'INTERVENTION',
    sourceTag: 'sys_man',
    timestamp: new Date().toISOString(),
    message: 'Preciso urgentemente manutenção técnica (alerta recorrente a cada 3 min)'
  };

  const msgMqtt = { payload: JSON.stringify(event) };

  if (shouldSendEmail) {
    // Atualiza o horário do último envio de e-mail
    flow.set('cpslai1_last_email_sent_at', now);

    node.status({
      fill: 'red',
      shape: 'dot',
      text: 'INTERVENTION — E-mail enviado (' + new Date().toLocaleTimeString('pt-BR') + ')'
    });

    const msgEmail = {
      to: 'sanitized-recipient@example.invalid',
      topic: 'Intervenção humana no CPS — ' + event.cpsName,
      payload: event.message
    };

    // Dispara tanto para o MQTT quanto para o E-mail
    return [msgMqtt, msgEmail];
  } else {
    // Se ainda não deu 3 minutos, envia apenas o MQTT e mantém status no nó
    const nextInSec = Math.ceil((EMAIL_INTERVAL_MS - (now - lastEmailSentAt)) / 1000);
    node.status({
      fill: 'yellow',
      shape: 'ring',
      text: 'MANUAL ativo — Próximo e-mail em ' + nextInSec + 's'
    });

    return [msgMqtt, null];
  }
}

// Reset das variáveis ao sair do modo MANUAL
if (['AUTOMATIC', 'INIT', 'STEP_BY_STEP'].includes(status.operationMode)) {
  flow.set('cpslai1_alert_intervention_active', false);
  flow.set('cpslai1_last_email_sent_at', 0); // Zera o temporizador
  if (isAlertActive) {
    node.status({ fill: 'green', shape: 'ring', text: 'Rearmado após sair do MANUAL' });
  }
}

return null;

const latest = global.get("cpslai1_latest") || {};
const lastMs = global.get("cpslai1_last_update_ms") || 0;
const opcStatus = global.get("cpslai1_opcua_status") || {};

const nowMs = Date.now();
const nowIso = new Date(nowMs).toISOString();

const ageMs = lastMs ? (nowMs - lastMs) : null;
const dataFresh = ageMs !== null && ageMs <= 5000;

function entry(field) {
    return latest[field] || null;
}

function val(field) {
    const e = entry(field);
    return e && e.value !== undefined ? e.value : null;
}

msg.statusCode = 200;
msg.headers = {
    "Content-Type": "application/json; charset=utf-8",
    "Access-Control-Allow-Origin": "*",
    "Cache-Control": "no-store"
};

msg.payload = {
    schemaVersion: "1.0",
    cpsId: "cpslai1",
    assetName: "DistributionConveyorStationLAI",
    displayName: "CPS-LAI-01 – Distribution/Conveyor Station",
    source: "OPC_UA",
    endpoint: "opc.tcp://192.168.1.10:4840",
    timestamp: nowIso,

    communication: {
        dataFresh,
        dataAgeMs: ageMs,
        opcUaStatus: opcStatus
    },

    data: {
        PieceAtEntry: val("PieceAtEntry"),
        PieceAtMiddle: val("PieceAtMiddle"),
        PieceAtExit: val("PieceAtExit"),

        SlideRetracted: val("SlideRetracted"),
        SlideExtended: val("SlideExtended"),

        MagazineFeedSensor: val("MagazineFeedSensor"),

        AlarmSignal: val("AlarmSignal")
    },

    evidence: latest
};

return msg;

const latest = global.get("cpslai1_latest") || {};
const lastMs = global.get("cpslai1_last_update_ms") || 0;
