const EMAIL_INTERVAL_MS = 3 * 60 * 1000;

const manualSignal = status.data?.sys_man;
const modeEvidence = status.derived;

const isManualMode =
    status.snapshotComplete === true &&
    modeEvidence?.operationMode === "MANUAL" &&
    manualSignal?.value === true &&
    manualSignal?.valid === true &&
    manualSignal?.stale === false;

const previousActive =
    flow.get("cpslai3_alert_intervention_active") === true;

const lastEmailSentAt =
    flow.get("cpslai3_last_email_sent_at") || 0;

// 1. INTERVENÇÃO ATIVA
if (isManualMode) {

    if (!previousActive) {
        flow.set("cpslai3_alert_intervention_active", true);
    }

    const shouldSendEmail =
        !previousActive ||
        (now - lastEmailSentAt) >= EMAIL_INTERVAL_MS;

    if (!shouldSendEmail) {
        const remaining = Math.max(0, Math.ceil(
            (EMAIL_INTERVAL_MS - (now - lastEmailSentAt)) / 1000
        ));

        node.status({
            fill: "yellow",
            shape: "ring",
            text: "MANUAL — próximo alerta em " + remaining + "s"
        });

        return null;
    }

    const event = {
        schemaVersion: "1.0",
        cpsId: "cpslai3",
        cpsName: "CPS-LAI-03 — Sorting Station",
        eventType: "HUMAN_INTERVENTION_REQUIRED",
        operationMode: "MANUAL",
        operationalState: "INTERVENTION",
        sourceTag: "sys_man",
        timestamp: new Date().toISOString(),
        message: "Preciso urgentemente manutenção técnica"
    };

    flow.set("cpslai3_last_email_sent_at", now);

    node.status({
        fill: "red",
        shape: "dot",
        text: "INTERVENTION — alerta encaminhado"
    });

    return [
        {
            payload: JSON.stringify(event)
        },
        {
            to: "sanitized-recipient@example.invalid",
            topic: "Intervenção humana no CPS — " + event.cpsName,
            payload: event.message
        }
    ];
}

